import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type UserRole = 'RESIDENT' | 'PROVIDER' | 'ADMIN';

export type TicketStatus = 'OPEN' | 'IN_PROGRESS' | 'RESOLVED';

export type TicketPriority = 'LOW' | 'HIGH';

export type ServiceCategory = 'PLUMBING' | 'ELECTRICIAN' | 'SECURITY' | 'SEWAGE';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  flatNumber?: string; // For residents
  trade?: ServiceCategory; // For providers
  isApproved: boolean;
}

export interface Ticket {
  id: string;
  userId: string; // Creator
  userName: string;
  category: ServiceCategory;
  description: string;
  priority: TicketPriority;
  status: TicketStatus;
  createdAt: number; // Timestamp
  updatedAt: number;
}

import React, { createContext, useContext, useState, ReactNode } from 'react';
import { Ticket, User, TicketStatus, UserRole } from '../types';

interface MockContextType {
  currentUser: User | null;
  tickets: Ticket[];
  users: User[];
  login: (role: UserRole) => void;
  logout: () => void;
  addTicket: (category: any, description: string, priority: any) => void;
  updateTicketStatus: (ticketId: string, status: TicketStatus) => void;
  approveUser: (userId: string) => void;
}

const MockContext = createContext<MockContextType | undefined>(undefined);

const INITIAL_USERS: User[] = [
  { id: 'u1', name: 'Rahul', role: 'RESIDENT', flatNumber: '101', isApproved: true },
  { id: 'u2', name: 'Ramesh', role: 'PROVIDER', trade: 'PLUMBING', isApproved: true },
  { id: 'u3', name: 'Secretary', role: 'ADMIN', isApproved: true },
  { id: 'u4', name: 'New Guy', role: 'RESIDENT', flatNumber: '202', isApproved: false },
];

const INITIAL_TICKETS: Ticket[] = [
  {
    id: 't1',
    userId: 'u1',
    userName: 'Rahul',
    category: 'PLUMBING',
    description: 'Kitchen sink is leaking.',
    priority: 'HIGH',
    status: 'OPEN',
    createdAt: Date.now() - 1000 * 60 * 30, // 30 mins ago
    updatedAt: Date.now(),
  },
  {
    id: 't2',
    userId: 'u1',
    userName: 'Rahul',
    category: 'ELECTRICIAN',
    description: 'Fan not working in bedroom.',
    priority: 'LOW',
    status: 'IN_PROGRESS',
    createdAt: Date.now() - 1000 * 60 * 60 * 2, // 2 hours ago
    updatedAt: Date.now(),
  },
  {
    id: 't3',
    userId: 'u1',
    userName: 'Rahul',
    category: 'SEWAGE',
    description: 'Bad smell coming from the drain.',
    priority: 'HIGH',
    status: 'OPEN',
    createdAt: Date.now() - 1000 * 60 * 60 * 5, // 5 hours ago (SLA BREACH)
    updatedAt: Date.now(),
  },
];

export const MockProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [tickets, setTickets] = useState<Ticket[]>(INITIAL_TICKETS);
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);

  const login = (role: UserRole) => {
    const user = users.find(u => u.role === role);
    if (user) setCurrentUser(user);
  };

  const logout = () => {
    setCurrentUser(null);
  };

  const addTicket = (category: any, description: string, priority: any) => {
    if (!currentUser) return;
    const newTicket: Ticket = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      userName: currentUser.name,
      category,
      description,
      priority,
      status: 'OPEN',
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };
    setTickets(prev => [newTicket, ...prev]);
  };

  const updateTicketStatus = (ticketId: string, status: TicketStatus) => {
    setTickets(prev => prev.map(t => 
      t.id === ticketId ? { ...t, status, updatedAt: Date.now() } : t
    ));
  };

  const approveUser = (userId: string) => {
    setUsers(prev => prev.map(u => 
      u.id === userId ? { ...u, isApproved: true } : u
    ));
  };

  return (
    <MockContext.Provider value={{
      currentUser,
      tickets,
      users,
      login,
      logout,
      addTicket,
      updateTicketStatus,
      approveUser
    }}>
      {children}
    </MockContext.Provider>
  );
};

export const useMock = () => {
  const context = useContext(MockContext);
  if (!context) throw new Error('useMock must be used within a MockProvider');
  return context;
};

import React from 'react';

export const Card: React.FC<{ children: React.ReactNode, className?: string, onClick?: () => void }> = ({ children, className = '', onClick }) => (
  <div onClick={onClick} className={`bg-white rounded-xl shadow-sm border border-gray-100 p-4 ${className} ${onClick ? 'cursor-pointer hover:shadow-md transition-shadow' : ''}`}>
    {children}
  </div>
);

export const Button: React.FC<{ 
  children: React.ReactNode, 
  onClick?: () => void, 
  variant?: 'primary' | 'secondary' | 'danger' | 'outline',
  className?: string,
  disabled?: boolean
}> = ({ children, onClick, variant = 'primary', className = '', disabled }) => {
  const baseStyle = "px-4 py-2 rounded-lg font-medium transition-colors flex items-center justify-center gap-2";
  const variants = {
    primary: "bg-primary text-white hover:bg-[#002855]",
    secondary: "bg-secondary text-gray-900 hover:bg-amber-400",
    danger: "bg-red-500 text-white hover:bg-red-600",
    outline: "border border-gray-300 text-gray-700 hover:bg-gray-50"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      className={`${baseStyle} ${variants[variant]} ${disabled ? 'opacity-50 cursor-not-allowed' : ''} ${className}`}
    >
      {children}
    </button>
  );
};

export const Badge: React.FC<{ children: React.ReactNode, color?: string, className?: string }> = ({ children, color = 'bg-gray-100 text-gray-800', className = '' }) => (
  <span className={`px-2 py-1 rounded-md text-xs font-semibold ${color} ${className}`}>
    {children}
  </span>
);

export const Input: React.FC<React.InputHTMLAttributes<HTMLInputElement>> = (props) => (
  <input 
    {...props} 
    className={`w-full px-4 py-2 rounded-lg border border-gray-300 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all ${props.className}`} 
  />
);

export const Select: React.FC<React.SelectHTMLAttributes<HTMLSelectElement>> = (props) => (
  <select 
    {...props} 
    className={`w-full px-4 py-2 rounded-lg border border-gray-300 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all ${props.className}`} 
  >
    {props.children}
  </select>
);

