import React, { useState } from 'react';
import { useMock } from '../context/MockContext';
import { Card, Button, Badge, Input, Select } from '../components/UI';
import { Ticket, ServiceCategory } from '../types';
import { Plus, Clock, CheckCircle, AlertCircle, Droplets, Zap, Shield, Trash2, X } from 'lucide-react';

const CATEGORIES: { id: ServiceCategory; label: string; icon: React.ReactNode }[] = [
  { id: 'PLUMBING', label: 'Plumbing', icon: <Droplets className="text-blue-500" /> },
  { id: 'ELECTRICIAN', label: 'Electrician', icon: <Zap className="text-yellow-500" /> },
  { id: 'SECURITY', label: 'Security', icon: <Shield className="text-green-500" /> },
  { id: 'SEWAGE', label: 'Sewage', icon: <Trash2 className="text-amber-700" /> },
];

const ResidentDashboard: React.FC = () => {
  const { tickets, currentUser, addTicket } = useMock();
  const [selectedCategory, setSelectedCategory] = useState<ServiceCategory | null>(null);
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<'LOW' | 'HIGH'>('LOW');

  const myTickets = tickets.filter(t => t.userId === currentUser?.id).sort((a, b) => b.createdAt - a.createdAt);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedCategory && description) {
      addTicket(selectedCategory, description, priority);
      setSelectedCategory(null);
      setDescription('');
      setPriority('LOW');
    }
  };

  return (
    <div className="space-y-6">
      <section>
        <h2 className="text-xl font-bold text-gray-900 mb-4">Request Service</h2>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {CATEGORIES.map((cat) => (
            <Card 
              key={cat.id} 
              onClick={() => setSelectedCategory(cat.id)}
              className="flex flex-col items-center justify-center p-6 hover:border-primary transition-colors gap-3"
            >
              <div className="p-3 bg-gray-50 rounded-full">{cat.icon}</div>
              <span className="font-medium text-gray-700">{cat.label}</span>
            </Card>
          ))}
        </div>
      </section>

      {/* Complaint Form Modal Overlay */}
      {selectedCategory && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white w-full max-w-md rounded-2xl p-6 shadow-xl animate-in fade-in zoom-in duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-primary">New {CATEGORIES.find(c => c.id === selectedCategory)?.label} Request</h3>
              <button onClick={() => setSelectedCategory(null)} className="text-gray-400 hover:text-gray-600">
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                <Input 
                  placeholder="Describe the issue..." 
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Priority</label>
                <div className="flex gap-4">
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input 
                      type="radio" 
                      name="priority" 
                      checked={priority === 'LOW'} 
                      onChange={() => setPriority('LOW')}
                      className="text-primary focus:ring-primary"
                    />
                    <span className="text-sm">Low</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input 
                      type="radio" 
                      name="priority" 
                      checked={priority === 'HIGH'} 
                      onChange={() => setPriority('HIGH')}
                      className="text-primary focus:ring-primary"
                    />
                    <span className="text-sm font-medium text-red-600">High</span>
                  </label>
                </div>
              </div>

              <div className="pt-4 flex gap-3">
                <Button type="button" variant="outline" onClick={() => setSelectedCategory(null)} className="flex-1">
                  Cancel
                </Button>
                <Button type="submit" className="flex-1">
                  Submit Complaint
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      <section>
        <h2 className="text-xl font-bold text-gray-900 mb-4">My History</h2>
        <div className="space-y-3">
          {myTickets.length === 0 ? (
            <p className="text-gray-500 text-center py-8">No tickets yet.</p>
          ) : (
            myTickets.map(ticket => (
              <Card key={ticket.id} className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="font-bold text-gray-900">{CATEGORIES.find(c => c.id === ticket.category)?.label}</span>
                    <span className="text-xs text-gray-400">• {new Date(ticket.createdAt).toLocaleString()}</span>
                  </div>
                  <p className="text-gray-600 text-sm">{ticket.description}</p>
                </div>
                <div className="flex items-center gap-3">
                   {ticket.priority === 'HIGH' && <Badge color="bg-red-100 text-red-700">High Priority</Badge>}
                   <StatusBadge status={ticket.status} />
                </div>
              </Card>
            ))
          )}
        </div>
      </section>
    </div>
  );
};

const StatusBadge: React.FC<{ status: Ticket['status'] }> = ({ status }) => {
  switch (status) {
    case 'OPEN': return <Badge color="bg-blue-100 text-blue-700">Open</Badge>;
    case 'IN_PROGRESS': return <Badge color="bg-secondary/20 text-amber-700">In Progress</Badge>;
    case 'RESOLVED': return <Badge color="bg-green-100 text-green-700">Resolved</Badge>;
    default: return null;
  }
};

export default ResidentDashboard;

import React from 'react';
import { useMock } from '../context/MockContext';
import { Card, Button, Badge } from '../components/UI';
import { TicketStatus } from '../types';
import { CheckCircle, PlayCircle, Clock } from 'lucide-react';

const ProviderDashboard: React.FC = () => {
  const { tickets, updateTicketStatus, currentUser } = useMock();

  // In a real app, filter by currentUser.trade. For Mock, we show all relevant or open tasks.
  // We'll show tasks that match the provider's trade OR are open if trade is generic.
  const myTasks = tickets.filter(t => 
    (t.category === currentUser?.trade) && t.status !== 'RESOLVED'
  ).sort((a, b) => b.priority === 'HIGH' ? 1 : -1);

  const completedTasks = tickets.filter(t => 
    (t.category === currentUser?.trade) && t.status === 'RESOLVED'
  );

  const handleStatusChange = (id: string, newStatus: TicketStatus) => {
    updateTicketStatus(id, newStatus);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
         <h2 className="text-xl font-bold text-gray-900">Active Tasks</h2>
         <Badge color="bg-blue-100 text-blue-800">{myTasks.length} Pending</Badge>
      </div>

      <div className="space-y-4">
        {myTasks.length === 0 ? (
           <div className="text-center py-12 bg-white rounded-xl border border-dashed border-gray-300">
             <p className="text-gray-500">No active tasks for your trade.</p>
           </div>
        ) : (
          myTasks.map(ticket => (
            <Card key={ticket.id} className="border-l-4 border-l-primary">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-2">
                    <span className="font-bold text-lg text-gray-900">{ticket.userName}</span>
                    <span className="text-sm text-gray-500">- Flat {ticket.userId === 'u1' ? '101' : 'Unknown'}</span>
                    {ticket.priority === 'HIGH' && (
                       <Badge color="bg-red-100 text-red-700 flex items-center gap-1">
                         High Priority
                       </Badge>
                    )}
                  </div>
                  <p className="text-gray-700 mb-2">{ticket.description}</p>
                  <p className="text-xs text-gray-400">Created: {new Date(ticket.createdAt).toLocaleString()}</p>
                </div>

                <div className="flex gap-2">
                  {ticket.status === 'OPEN' && (
                    <Button onClick={() => handleStatusChange(ticket.id, 'IN_PROGRESS')} variant="secondary" className="w-full md:w-auto">
                      <PlayCircle size={18} /> Accept Job
                    </Button>
                  )}
                  {ticket.status === 'IN_PROGRESS' && (
                    <Button onClick={() => handleStatusChange(ticket.id, 'RESOLVED')} variant="primary" className="w-full md:w-auto">
                      <CheckCircle size={18} /> Mark Done
                    </Button>
                  )}
                </div>
              </div>
            </Card>
          ))
        )}
      </div>

      <div className="pt-8 opacity-60">
        <h3 className="text-lg font-bold text-gray-900 mb-4">Completed Today</h3>
        {completedTasks.map(ticket => (
             <div key={ticket.id} className="flex justify-between items-center py-3 border-b border-gray-100">
                <span className="text-gray-600 line-through">{ticket.description}</span>
                <span className="text-green-600 text-sm font-medium">Done</span>
             </div>
        ))}
      </div>
    </div>
  );
};

export default ProviderDashboard;

import React from 'react';
import { useMock } from '../context/MockContext';
import { Card, Button, Badge } from '../components/UI';
import { AlertTriangle, Check, X, User } from 'lucide-react';

const AdminDashboard: React.FC = () => {
  const { tickets, users, approveUser } = useMock();

  // SLA Logic: Status != RESOLVED AND TimeElapsed > 4 hours
  const isSlaBreached = (ticket: any) => {
    const timeElapsed = Date.now() - ticket.createdAt;
    const hoursElapsed = timeElapsed / (1000 * 60 * 60);
    return ticket.status !== 'RESOLVED' && hoursElapsed > 4;
  };

  const slaBreachedTickets = tickets.filter(isSlaBreached);
  const normalTickets = tickets.filter(t => !isSlaBreached(t));
  const pendingUsers = users.filter(u => !u.isApproved);

  return (
    <div className="space-y-8">

      {/* SLA Monitor Section */}
      <section>
        <div className="flex items-center gap-3 mb-4">
          <h2 className="text-xl font-bold text-gray-900">SLA Monitor</h2>
          {slaBreachedTickets.length > 0 && (
             <Badge color="bg-red-600 text-white animate-pulse">
               {slaBreachedTickets.length} Breaches Detected
             </Badge>
          )}
        </div>

        <div className="space-y-4">
          {slaBreachedTickets.map(ticket => (
            <Card key={ticket.id} className="border border-red-200 bg-red-50/50">
              <div className="flex flex-col sm:flex-row justify-between gap-4">
                <div>
                   <div className="flex items-center gap-2 mb-1">
                      <span className="font-bold text-red-700 flex items-center gap-1">
                        <AlertTriangle size={16} /> SLA BREACH
                      </span>
                      <span className="text-sm text-gray-600">ID: #{ticket.id}</span>
                   </div>
                   <p className="font-medium text-gray-900">{ticket.category} - {ticket.userName}</p>
                   <p className="text-gray-600 text-sm mb-2">{ticket.description}</p>
                   <p className="text-xs text-red-600 font-mono">
                     Open for {Math.floor((Date.now() - ticket.createdAt) / (1000 * 60 * 60))} hours
                   </p>
                </div>
                <div className="flex items-center">
                  <Badge color="bg-white text-gray-800 border border-gray-200">{ticket.status}</Badge>
                </div>
              </div>
            </Card>
          ))}

          {slaBreachedTickets.length === 0 && (
            <div className="p-4 bg-green-50 border border-green-100 rounded-lg text-green-700 text-sm">
              All systems normal. No SLA breaches.
            </div>
          )}
        </div>
      </section>

      <section>
        <h2 className="text-xl font-bold text-gray-900 mb-4">All Tickets</h2>
         <div className="overflow-x-auto bg-white rounded-xl shadow-sm border border-gray-200">
           <table className="w-full text-left text-sm">
             <thead className="bg-gray-50 text-gray-600 border-b border-gray-200">
               <tr>
                 <th className="p-4 font-medium">User</th>
                 <th className="p-4 font-medium">Category</th>
                 <th className="p-4 font-medium">Status</th>
                 <th className="p-4 font-medium">Priority</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-gray-100">
               {normalTickets.map(t => (
                 <tr key={t.id} className="hover:bg-gray-50">
                   <td className="p-4">{t.userName}</td>
                   <td className="p-4">{t.category}</td>
                   <td className="p-4">
                     <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                       t.status === 'OPEN' ? 'bg-blue-100 text-blue-700' : 
                       t.status === 'IN_PROGRESS' ? 'bg-amber-100 text-amber-700' : 'bg-green-100 text-green-700'
                     }`}>
                       {t.status}
                     </span>
                   </td>
                   <td className="p-4">{t.priority}</td>
                 </tr>
               ))}
             </tbody>
           </table>
         </div>
      </section>

      {/* User Management Section */}
      <section>
        <h2 className="text-xl font-bold text-gray-900 mb-4">User Approvals</h2>
        <div className="grid gap-4 md:grid-cols-2">
          {pendingUsers.length === 0 ? (
            <p className="text-gray-500 text-sm col-span-2">No new users waiting for approval.</p>
          ) : (
            pendingUsers.map(user => (
              <Card key={user.id} className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="bg-gray-100 p-2 rounded-full">
                    <User size={20} className="text-gray-600" />
                  </div>
                  <div>
                    <p className="font-bold text-gray-900">{user.name}</p>
                    <p className="text-xs text-gray-500">{user.role} {user.flatNumber ? `- ${user.flatNumber}` : ''}</p>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors">
                    <X size={20} />
                  </button>
                  <button 
                    onClick={() => approveUser(user.id)}
                    className="p-2 text-green-500 hover:bg-green-50 rounded-lg transition-colors"
                  >
                    <Check size={20} />
                  </button>
                </div>
              </Card>
            ))
          )}
        </div>
      </section>
    </div>
  );
};

